import React, { useState, useEffect } from 'react';
import { Trending, Recommendations, Search } from './components';
import { api } from './services/api';
import { FiSun, FiMoon, FiTrendingUp, FiUser, FiSearch } from 'react-icons/fi';
import './App.css';

function App() {
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState('trending');
  const [loading, setLoading] = useState(false);
  const [trendingTopics, setTrendingTopics] = useState([]);
  const [userPreferences, setUserPreferences] = useState(['technology', 'science']);
  const [showPreferences, setShowPreferences] = useState(false);

  const availableTopics = [
    'technology', 'science', 'health', 'business', 'environment',
    'politics', 'entertainment', 'sports'
  ];

  // Fetch trending topics
  useEffect(() => {
    const fetchTrendingTopics = async () => {
      try {
        const topics = await api.getTrendingTopics();
        setTrendingTopics(topics);
      } catch (error) {
        console.error('Error fetching trending topics:', error);
      }
    };
    fetchTrendingTopics();
  }, []);

  // Update body class for dark/light mode
  useEffect(() => {
    document.body.className = darkMode ? 'dark-mode' : 'light-mode';
  }, [darkMode]);

  const handlePreferenceChange = (pref) => {
    setUserPreferences(prev =>
      prev.includes(pref) ? prev.filter(p => p !== pref) : [...prev, pref]
    );
  };

  const savePreferences = async () => {
    try {
      setLoading(true);
      await api.updateUserPreferences(1, userPreferences);
      setShowPreferences(false);
    } catch (error) {
      console.error('Error saving preferences:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`app ${darkMode ? 'dark' : 'light'}`}>
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <h1 className="logo">🤖 AI News Aggregator</h1>
          <div className="header-actions">
            <button className="preferences-btn" onClick={() => setShowPreferences(!showPreferences)}>
              <FiUser /> Preferences
            </button>
            <button className="theme-toggle" onClick={() => setDarkMode(!darkMode)}>
              {darkMode ? <FiSun /> : <FiMoon />}
            </button>
          </div>
        </div>
      </header>

      {/* Preferences Modal */}
      {showPreferences && (
        <div className="preferences-modal">
          <div className="preferences-content">
            <h3>Your Interests</h3>
            <p>Select topics you're interested in:</p>
            <div className="preferences-grid">
              {availableTopics.map(topic => (
                <label key={topic} className="preference-item">
                  <input
                    type="checkbox"
                    checked={userPreferences.includes(topic)}
                    onChange={() => handlePreferenceChange(topic)}
                  />
                  <span className="preference-label">{topic}</span>
                </label>
              ))}
            </div>
            <div className="preferences-actions">
              <button className="btn btn-primary" onClick={savePreferences} disabled={loading}>
                {loading ? 'Saving...' : 'Save Preferences'}
              </button>
              <button className="btn btn-secondary" onClick={() => setShowPreferences(false)}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Tabs */}
      <nav className="tabs">
        <button className={`tab ${activeTab === 'trending' ? 'active' : ''}`} onClick={() => setActiveTab('trending')}>
          <FiTrendingUp /> Trending
        </button>
        <button className={`tab ${activeTab === 'recommendations' ? 'active' : ''}`} onClick={() => setActiveTab('recommendations')}>
          <FiUser /> For You
        </button>
        <button className={`tab ${activeTab === 'search' ? 'active' : ''}`} onClick={() => setActiveTab('search')}>
          <FiSearch /> Search
        </button>
      </nav>

      {/* Trending Topics Bar */}
      <div className="trending-topics-bar">
        <span className="trending-label">🔥 Trending: </span>
        {trendingTopics.map((topic, index) => (
          <span key={index} className="trending-topic">#{topic}</span>
        ))}
      </div>

      {/* Main Content */}
      <main className="main-content">
        {activeTab === 'trending' && <Trending />}
        {activeTab === 'recommendations' && <Recommendations userId={1} preferences={userPreferences} />}
        {activeTab === 'search' && <Search />}
      </main>
    </div>
  );
}

export default App;
